using namespace phosphor::led::utils;

/** @class Monitor
 *  @brief Implementation of LED handling during the change of the Functional
 *         property of the OperationalStatus interface
 *
 *  @details This implements methods for watching OperationalStatus interface of
 *           Inventory D-Bus object and then assert corresponding LED Group
 *           D-Bus objects.
 */
class Monitor
{
  public:
    Monitor() = delete;
    ~Monitor() = default;
    Monitor(const Monitor&) = delete;
    Monitor& operator=(const Monitor&) = delete;
    Monitor(Monitor&&) = default;
    Monitor& operator=(Monitor&&) = delete;

    /** @brief Add a watch for OperationalStatus.
     *
     *  @param[in] bus -  D-Bus object
     */
    explicit Monitor(sdbusplus::bus_t& bus) :
        matchSignal(bus,
                    "type='signal',member='PropertiesChanged', "
                    "interface='org.freedesktop.DBus.Properties', "
                    "sender='xyz.openbmc_project.Inventory.Manager', "
                    "arg0namespace='xyz.openbmc_project.State.Decorator."
                    "OperationalStatus'",
                    [](sdbusplus::message_t& m) { matchHandler(m); })

    {}

  private:
    /** @brief sdbusplus signal matches for Monitor */
    sdbusplus::bus::match_t matchSignal;

    /**
     * @brief Callback handler that gets invoked when the PropertiesChanged
     *        signal is caught by this app. Message is scanned for Inventory
     *        D-Bus object path and if OperationalStatus::Functional is changed,
     *        then corresponding LED Group D-Bus object is called to assert.
     *
     * @param[in] msg - The D-Bus message contents
     */
    static void matchHandler(sdbusplus::message_t& msg);

    /**
     * @brief From the Inventory D-Bus object, obtains the associated LED group
     *        D-Bus object, where the association name is "fault_led_group"
     *
     * @param[in] inventoryPath         - Inventory D-Bus object path
     *
     * @return std::vector<std::string> - Vector of LED Group D-Bus object paths
     */
    static std::vector<std::string> getLedGroupPaths(
        const std::string& inventoryPath);

    /**
     * @brief Update the Asserted property of the LED Group Manager.
     *
     * @param[in] ledGroupPaths   - LED Group D-Bus object Paths
     * @param[in] value           - The Asserted property value, True / False
     */
    static void updateAssertedProperty(
        const std::vector<std::string>& ledGroupPaths, bool value);
};
} // namespace monitor
} // namespace status
} // namespace Operational
} // namespace led
} // namespace phosphor

#include "json-parser.hpp"

#include <gtest/gtest.h>

TEST(loadJsonConfig, testGoodPath)
{
    static constexpr auto jsonPath = "config/led-group-config.json";
    auto ledMap = loadJsonConfig(jsonPath);

    std::string objPath = "/xyz/openbmc_project/led/groups";
    std::string bmcBooted = objPath + "/bmc_booted";
    std::string powerOn = objPath + "/power_on";
    std::string powerOff = objPath + "/power_off";
    std::string enclosureIdentify = objPath + "/enclosure_identify";

    ASSERT_EQ(ledMap.contains(bmcBooted), true);
    ASSERT_EQ(ledMap.contains(powerOn), true);
    ASSERT_EQ(ledMap.contains(powerOff), true);
    ASSERT_EQ(ledMap.contains(enclosureIdentify), true);

    auto& bmcBootedActions = ledMap.at(bmcBooted).actionSet;
    auto& powerOnActions = ledMap.at(powerOn).actionSet;
    auto& powerOffActions = ledMap.at(powerOff).actionSet;
    auto& enclosureIdentifyActions = ledMap.at(enclosureIdentify).actionSet;

    for (const auto& group : bmcBootedActions)
    {
        ASSERT_EQ(group.name, "heartbeat");
        ASSERT_EQ(group.action, phosphor::led::Layout::Action::On);
        ASSERT_EQ(group.dutyOn, 50);
        ASSERT_EQ(group.period, 0);
        ASSERT_EQ(group.priority, phosphor::led::Layout::Action::Blink);
    }

    for (const auto& group : powerOnActions)
    {
        ASSERT_EQ(group.name, "power");
        ASSERT_EQ(group.action, phosphor::led::Layout::Action::On);
        ASSERT_EQ(group.dutyOn, 50);
        ASSERT_EQ(group.period, 0);
        ASSERT_EQ(group.priority, phosphor::led::Layout::Action::On);
    }
    for (const auto& group : powerOffActions)
    {
        ASSERT_EQ(group.name, "power_off_led");
        ASSERT_EQ(group.action, phosphor::led::Layout::Action::Off);
        ASSERT_EQ(group.priority, phosphor::led::Layout::Action::Off);
    }

    for (const auto& group : enclosureIdentifyActions)
    {
        if (group.name == "front_id")
        {
            ASSERT_EQ(group.action, phosphor::led::Layout::Action::Blink);
            ASSERT_EQ(group.dutyOn, 50);
            ASSERT_EQ(group.period, 1000);
            ASSERT_EQ(group.priority, phosphor::led::Layout::Action::Blink);
        }
        else if (group.name == "rear_id")
        {
            ASSERT_EQ(group.action, phosphor::led::Layout::Action::Blink);
            ASSERT_EQ(group.dutyOn, 50);
            ASSERT_EQ(group.period, 1000);
            ASSERT_EQ(group.priority, phosphor::led::Layout::Action::Blink);
        }
        else
        {
            ASSERT_TRUE(false);
        }
    }
}

#include "operational-status-monitor.hpp"

#include <phosphor-logging/elog.hpp>
#include <phosphor-logging/lg2.hpp>
#include <xyz/openbmc_project/Association/common.hpp>
#include <xyz/openbmc_project/Led/Group/common.hpp>

using LedGroup = sdbusplus::common::xyz::openbmc_project::led::Group;
using Association = sdbusplus::common::xyz::openbmc_project::Association;

namespace phosphor
{
namespace led
{
namespace Operational
{
namespace status
{
namespace monitor
{

void Monitor::matchHandler(sdbusplus::message_t& msg)
{
    // Get the ObjectPath of the `xyz.openbmc_project.Inventory.Manager`
    // service
    std::string invObjectPath = msg.get_path();

    // Get all the properties of
    // "xyz.openbmc_project.State.Decorator.OperationalStatus" interface
    std::string interfaceName{};
    std::unordered_map<std::string, std::variant<bool>> properties;
    msg.read(interfaceName, properties);

    const auto it = properties.find("Functional");
    if (it != properties.end())
    {
        const bool* value = std::get_if<bool>(&it->second);
        if (value == nullptr)
        {
            lg2::error(
                "Failed to get the Functional property, INVENTORY_PATH = {PATH}",
                "PATH", invObjectPath);
            return;
        }

        // See if the Inventory D-Bus object has an association with LED groups
        // D-Bus object.
        auto ledGroupPath = getLedGroupPaths(invObjectPath);
        if (ledGroupPath.empty())
        {
            lg2::info(
                "The inventory D-Bus object is not associated with the LED "
                "group D-Bus object. INVENTORY_PATH = {PATH}",
                "PATH", invObjectPath);
            return;
        }

        // Update the Asserted property by the Functional property value.
        updateAssertedProperty(ledGroupPath, *value);
    }
}

std::vector<std::string> Monitor::getLedGroupPaths(
    const std::string& inventoryPath)
{
    // Get endpoints from fType
    std::string faultLedAssociation = inventoryPath + "/fault_identifying";

    // endpoint contains the vector of strings, where each string is a Inventory
    // D-Bus object that this, associated with this LED Group D-Bus object
    // pointed to by fru_fault
    PropertyValue endpoint{};

    try
    {
        endpoint = phosphor::led::utils::DBusHandler::getProperty(
            faultLedAssociation, Association::interface,
            Association::property_names::endpoints);
    }
    catch (const sdbusplus::exception_t& e)
    {
        lg2::error(
            "Failed to get endpoints property, ERROR = {ERROR}, PATH = {PATH}",
            "ERROR", e, "PATH", faultLedAssociation);

        return {};
    }

    return std::get<std::vector<std::string>>(endpoint);
}

void Monitor::updateAssertedProperty(
    const std::vector<std::string>& ledGroupPaths, bool value)
{
    for (const auto& path : ledGroupPaths)
    {
        try
        {
            // Call "Group Asserted --> true" if the value of Functional is
            // false Call "Group Asserted --> false" if the value of Functional
            // is true
            PropertyValue assertedValue{!value};
            phosphor::led::utils::DBusHandler::setProperty(
                path, LedGroup::interface, LedGroup::property_names::asserted,
                assertedValue);
        }
        catch (const sdbusplus::exception_t& e)
        {
            lg2::error(
                "Failed to set Asserted property, ERROR = {ERROR}, PATH = {PATH}",
                "ERROR", e, "PATH", path);
        }
    }
}
} // namespace monitor
} // namespace status
} // namespace Operational
} // namespace led
} // namespace phosphor

#pragma once

#include "../utils.hpp"
#include "leak-detector-config.hpp"

#include <sdbusplus/bus.hpp>
#include <sdbusplus/bus/match.hpp>
#include <sdbusplus/server.hpp>

#include <string>
#include <unordered_set>

namespace phosphor
{
namespace led
{
namespace leakdetector
{
namespace monitor
{

/** @class Monitor
 *  @brief Watches xyz.openbmc_project.State.LeakDetector objects and drives
 *         a configured LED group based on whether any detector is in the
 *         Critical state.
 *
 *  @details
 *  The LED group is asserted as soon as any detector reports Critical, and
 *  is only deasserted once every detector has left the Critical state. The
 *  set of currently-Critical detectors is tracked by D-Bus object path so
 *  that the LED is not deasserted while at least one detector remains
 *  Critical.
 */
class Monitor
{
  public:
    Monitor() = delete;
    ~Monitor() = default;
    Monitor(const Monitor&) = delete;
    Monitor& operator=(const Monitor&) = delete;
    Monitor(Monitor&&) = delete;
    Monitor& operator=(Monitor&&) = delete;

    /** @brief Construct a leak detector monitor.
     *
     *  Sets up signal matches for property changes and interface
     *  add/remove events, then performs an initial scan via ObjectMapper
     *  to seed state from any detectors that are already on the bus.
     *
     *  @param[in] bus    - The D-Bus bus object
     *  @param[in] config - Runtime configuration (LED group name).
     */
    Monitor(sdbusplus::bus_t& bus, config::Config config);

  private:
    /** @brief D-Bus connection. */
    sdbusplus::bus_t& bus;

    /** @brief Runtime configuration (LED group name). */
    config::Config config;

    /** @brief Object paths of detectors currently observed in the Critical
     *         state. The LED group is asserted iff this set is non-empty.
     */
    std::unordered_set<std::string> criticalDetectors;

    /** @brief Watch for DetectorState property changes. */
    sdbusplus::bus::match_t propertiesChangedMatch;

    /** @brief Watch for new LeakDetector objects appearing at runtime. */
    sdbusplus::bus::match_t interfacesAddedMatch;

    /** @brief Watch for LeakDetector objects being removed at runtime. */
    sdbusplus::bus::match_t interfacesRemovedMatch;

    /** @brief Walk the bus via ObjectMapper for any existing detectors and
     *         seed criticalDetectors with the ones currently in Critical.
     */
    void processExistingDetectors();

    /** @brief Update tracked state for a single detector path.
     *
     *  Inserts or removes the path from criticalDetectors based on
     *  whether @p state represents Critical, and toggles the LED group
     *  on the appropriate empty <-> non-empty transitions.
     *
     *  @param[in] path  - Detector D-Bus object path
     *  @param[in] state - Current DetectorState string for that detector.
     */
    void updateDetectorState(const std::string& path, const std::string& state);

    /** @brief Forget a detector path entirely (e.g. when its object is
     *         removed). Drops the LED group if this empties the set.
     */
    void forgetDetector(const std::string& path);

    /** @brief PropertiesChanged signal handler. */
    void onPropertiesChanged(sdbusplus::message_t& msg);

    /** @brief InterfacesAdded signal handler. */
    void onInterfacesAdded(sdbusplus::message_t& msg);

    /** @brief InterfacesRemoved signal handler. */
    void onInterfacesRemoved(sdbusplus::message_t& msg);

    /** @brief Set the Asserted property of the configured LED group. */
    void setLeakCriticalLed(bool asserted);
};

} // namespace monitor
} // namespace leakdetector
} // namespace led
} // namespace phosphor

#include "leak-detector-monitor.hpp"

#include <phosphor-logging/lg2.hpp>
#include <xyz/openbmc_project/Led/Group/common.hpp>
#include <xyz/openbmc_project/State/LeakDetector/common.hpp>

#include <algorithm>

namespace phosphor
{
namespace led
{
namespace leakdetector
{
namespace monitor
{

namespace
{

using LeakDetector =
    sdbusplus::common::xyz::openbmc_project::state::LeakDetector;
using LedGroup = sdbusplus::common::xyz::openbmc_project::led::Group;

constexpr auto LEAK_DETECTOR_INTERFACE = LeakDetector::interface;
constexpr auto DETECTOR_STATE_PROPERTY = "DetectorState";

const auto CRITICAL_STATE = LeakDetector::convertDetectorStateEnumToString(
    LeakDetector::DetectorStateEnum::Critical);

constexpr auto LED_GROUP_PATH_PREFIX = "/xyz/openbmc_project/led/groups/";
constexpr auto LED_GROUP_INTERFACE = LedGroup::interface;
constexpr auto LED_GROUP_ASSERTED_PROPERTY = "Asserted";

constexpr auto OBJECT_ROOT = "/xyz/openbmc_project/state";

bool isCriticalState(const std::string& state)
{
    return state == CRITICAL_STATE;
}

} // namespace

Monitor::Monitor(sdbusplus::bus_t& busIn, config::Config configIn) :
    bus(busIn), config(std::move(configIn)),
    propertiesChangedMatch(
        bus,
        sdbusplus::bus::match::rules::propertiesChangedNamespace(
            OBJECT_ROOT, LEAK_DETECTOR_INTERFACE),
        [this](sdbusplus::message_t& m) { onPropertiesChanged(m); }),
    interfacesAddedMatch(
        bus, sdbusplus::bus::match::rules::interfacesAddedAtPath(OBJECT_ROOT),
        [this](sdbusplus::message_t& m) { onInterfacesAdded(m); }),
    interfacesRemovedMatch(
        bus, sdbusplus::bus::match::rules::interfacesRemovedAtPath(OBJECT_ROOT),
        [this](sdbusplus::message_t& m) { onInterfacesRemoved(m); })
{
    processExistingDetectors();
}

void Monitor::processExistingDetectors()
{
    std::vector<std::string> paths;
    try
    {
        paths = phosphor::led::utils::DBusHandler::getSubTreePaths(
            OBJECT_ROOT, LEAK_DETECTOR_INTERFACE);
    }
    catch (const sdbusplus::exception_t& e)
    {
        // Likely no LeakDetector objects exist yet. That's fine; we'll
        // pick them up when InterfacesAdded fires.
        lg2::info("No existing leak detectors found, ERROR = {ERROR}", "ERROR",
                  e);
        return;
    }

    for (const auto& path : paths)
    {
        try
        {
            auto value = phosphor::led::utils::DBusHandler::getProperty(
                path, LEAK_DETECTOR_INTERFACE, DETECTOR_STATE_PROPERTY);
            const auto* state = std::get_if<std::string>(&value);
            if (state == nullptr)
            {
                lg2::error(
                    "DetectorState property is not a string, PATH = {PATH}",
                    "PATH", path);
                continue;
            }
            updateDetectorState(path, *state);
        }
        catch (const sdbusplus::exception_t& e)
        {
            lg2::error(
                "Failed to read DetectorState, PATH = {PATH}, ERROR = {ERROR}",
                "PATH", path, "ERROR", e);
        }
    }
}

void Monitor::updateDetectorState(const std::string& path,
                                  const std::string& state)
{
    const bool wasEmpty = criticalDetectors.empty();

    if (isCriticalState(state))
    {
        const auto [_, inserted] = criticalDetectors.insert(path);
        if (inserted)
        {
            lg2::info("Leak detector entered Critical state, PATH = {PATH}",
                      "PATH", path);
        }
    }
    else
    {
        const auto erased = criticalDetectors.erase(path);
        if (erased > 0)
        {
            lg2::info(
                "Leak detector left Critical state, PATH = {PATH}, STATE = {STATE}",
                "PATH", path, "STATE", state);
        }
    }

    const bool isEmpty = criticalDetectors.empty();
    if (wasEmpty && !isEmpty)
    {
        setLeakCriticalLed(true);
    }
    else if (!wasEmpty && isEmpty)
    {
        setLeakCriticalLed(false);
    }
}

void Monitor::forgetDetector(const std::string& path)
{
    const bool wasEmpty = criticalDetectors.empty();
    const auto erased = criticalDetectors.erase(path);
    if (erased == 0)
    {
        return;
    }

    lg2::info("Leak detector removed while Critical, PATH = {PATH}", "PATH",
              path);

    if (!wasEmpty && criticalDetectors.empty())
    {
        setLeakCriticalLed(false);
    }
}

void Monitor::onPropertiesChanged(sdbusplus::message_t& msg)
{
    try
    {
        auto value = phosphor::led::utils::DBusHandler::getProperty(
            msg.get_path(), LEAK_DETECTOR_INTERFACE, DETECTOR_STATE_PROPERTY);
        const auto* state = std::get_if<std::string>(&value);
        if (state == nullptr)
        {
            lg2::error("DetectorState property is not a string, PATH = {PATH}",
                       "PATH", msg.get_path());
            return;
        }
        updateDetectorState(msg.get_path(), *state);
    }
    catch (const sdbusplus::exception_t& e)
    {
        lg2::error(
            "Failed to read DetectorState on PropertiesChanged, PATH = {PATH}, ERROR = {ERROR}",
            "PATH", msg.get_path(), "ERROR", e);
    }
}

void Monitor::onInterfacesAdded(sdbusplus::message_t& msg)
{
    sdbusplus::object_path objectPath;
    try
    {
        msg.read(objectPath);
    }
    catch (const sdbusplus::exception_t&)
    {
        return;
    }

    try
    {
        auto value = phosphor::led::utils::DBusHandler::getProperty(
            objectPath.str, LEAK_DETECTOR_INTERFACE, DETECTOR_STATE_PROPERTY);
        const auto* state = std::get_if<std::string>(&value);
        if (state == nullptr)
        {
            lg2::error("DetectorState property is not a string, PATH = {PATH}",
                       "PATH", objectPath.str);
            return;
        }
        updateDetectorState(objectPath.str, *state);
    }
    catch (const sdbusplus::exception_t&)
    {
        // Not a leak detector or not yet readable -- ignore.
    }
}

void Monitor::onInterfacesRemoved(sdbusplus::message_t& msg)
{
    sdbusplus::object_path objectPath;
    std::vector<std::string> interfaces;
    try
    {
        msg.read(objectPath, interfaces);
    }
    catch (const sdbusplus::exception_t& e)
    {
        lg2::error("Failed to parse InterfacesRemoved, ERROR = {ERROR}",
                   "ERROR", e);
        return;
    }

    if (std::find(interfaces.begin(), interfaces.end(),
                  LEAK_DETECTOR_INTERFACE) == interfaces.end())
    {
        return;
    }

    forgetDetector(objectPath.str);
}

void Monitor::setLeakCriticalLed(bool asserted)
{
    const auto* assertedStr = asserted ? "true" : "false";
    const std::string ledPath =
        std::string{LED_GROUP_PATH_PREFIX} + config.criticalLedGroup;

    lg2::info(
        "Updating leak critical LED group, GROUP = {GROUP}, ASSERTED = {ASSERTED}",
        "GROUP", config.criticalLedGroup, "ASSERTED", assertedStr);
    try
    {
        phosphor::led::utils::DBusHandler::setProperty(
            ledPath, LED_GROUP_INTERFACE, LED_GROUP_ASSERTED_PROPERTY,
            phosphor::led::utils::PropertyValue{asserted});
    }
    catch (const sdbusplus::exception_t& e)
    {
        lg2::error(
            "Failed to set leak critical LED group, GROUP = {GROUP}, ASSERTED = {ASSERTED}, ERROR = {ERROR}",
            "GROUP", config.criticalLedGroup, "ASSERTED", assertedStr, "ERROR",
            e);
    }
}

